from pathlib import Path
p=Path('cms-link-enhancements.js')
s=p.read_text(encoding='utf-8')
a=s.index('function openCropModal()')
b=s.index("$e('cmsCropStage').onclick",a)
fn=r'''function openCropModal(){const im=currentImage();if(!im||blockStyle==='simple')return;const m=document.createElement('div');m.className='cms-crop-modal';const fixedRatio=blockStyle==='thumbnail'?1:blockStyle==='background'?3.6:null;m.innerHTML=`<button class="cms-crop-close" type="button" aria-label="닫기">×</button><div class="cms-crop-work"><img src="${esc(im)}"><div class="cms-crop-frame"></div></div><div class="cms-crop-help">크기, 위치를 자유롭게 변경하여<br>표시 영역을 조정할 수 있습니다</div><div class="cms-crop-actions"><button class="cms-crop-cancel" type="button">취소</button><button class="cms-crop-apply" type="button">선택</button></div>`;document.body.appendChild(m);const work=m.querySelector('.cms-crop-work'),img=m.querySelector('img'),frame=m.querySelector('.cms-crop-frame');frame.innerHTML='';frame.style.cssText='position:absolute;inset:0;border:2px solid #8062d8;cursor:grab;touch-action:none';let scale=Math.max(1,zoom),tx=(50-px)/100*work.clientWidth,ty=(50-py)/100*work.clientHeight,drag=null;const setViewport=()=>{if(blockStyle==='thumbnail'){work.style.width='min(560px,82vw)';work.style.aspectRatio='1';work.style.height='auto'}else if(blockStyle==='background'){work.style.width='min(690px,82vw)';work.style.aspectRatio='3.6/1';work.style.height='auto'}else{work.style.width='min(690px,82vw)';work.style.aspectRatio='1';work.style.height='auto'}};setViewport();const paint=()=>{img.style.position='absolute';img.style.left='50%';img.style.top='50%';img.style.width='100%';img.style.height='auto';img.style.maxWidth='none';img.style.transformOrigin='center';img.style.transform=`translate(calc(-50% + ${tx}px),calc(-50% + ${ty}px)) scale(${scale})`};img.onload=()=>{if(blockStyle==='card'&&img.naturalWidth&&img.naturalHeight){work.style.aspectRatio=`${img.naturalWidth}/${img.naturalHeight}`;work.style.height='auto'}paint()};frame.onpointerdown=e=>{e.preventDefault();frame.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,tx,ty};frame.style.cursor='grabbing'};frame.onpointermove=e=>{if(!drag)return;tx=drag.tx+(e.clientX-drag.x);ty=drag.ty+(e.clientY-drag.y);paint()};const end=e=>{drag=null;frame.style.cursor='grab';try{frame.releasePointerCapture(e.pointerId)}catch(_){}};frame.onpointerup=end;frame.onpointercancel=end;work.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(1,Math.min(5,scale*(e.deltaY<0?1.08:.92)));paint()},{passive:false});let pinch=null;work.addEventListener('touchstart',e=>{if(e.touches.length===2){const [u,v]=e.touches;pinch={d:Math.hypot(u.clientX-v.clientX,u.clientY-v.clientY),s:scale}}},{passive:true});work.addEventListener('touchmove',e=>{if(pinch&&e.touches.length===2){e.preventDefault();const [u,v]=e.touches;scale=Math.max(1,Math.min(5,pinch.s*Math.hypot(u.clientX-v.clientX,u.clientY-v.clientY)/pinch.d));paint()}},{passive:false});work.addEventListener('touchend',()=>pinch=null);const close=()=>m.remove();m.querySelector('.cms-crop-close').onclick=close;m.querySelector('.cms-crop-cancel').onclick=close;m.querySelector('.cms-crop-apply').onclick=()=>{zoom=scale;px=Math.max(0,Math.min(100,50-tx/Math.max(1,work.clientWidth)*100));py=Math.max(0,Math.min(100,50-ty/Math.max(1,work.clientHeight)*100));close();render()}}
'''
s=s[:a]+fn+s[b:]
p.write_text(s,encoding='utf-8')
